CREATE PROCEDURE dbo.UpdateSjJournalAtomic @JournalIdNo int,@TransactionDate date,@AccountIdNo smallint,@ReferenceNo varchar(15)=NULL,@Notes nvarchar(300)=NULL,@Approved bit=0,@Posted bit=0,@Cancelled bit=0,@Items dbo.JournalItemInsert READONLY,@Deposits dbo.SalesDepositInsert READONLY
AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;IF NOT EXISTS(SELECT 1 FROM dbo.SalesJournal WHERE IdNo=@JournalIdNo) THROW 51420,'Sales journal was not found.',1;IF EXISTS(SELECT 1 FROM dbo.SalesJournal WHERE IdNo=@JournalIdNo AND Posted=1) THROW 51421,'Posted sales journals cannot be edited.',1;IF EXISTS(SELECT 1 FROM dbo.SalesJournalItem i JOIN dbo.Reconciled r ON r.JournalCode='SJ' AND r.JournalItemIdNo=i.IdNo WHERE i.JournalIdNo=@JournalIdNo) THROW 51422,'Reconciled sales journals cannot be edited.',1;IF @TransactionDate>='20260101' AND (NOT EXISTS(SELECT 1 FROM @Items) OR ABS((SELECT COALESCE(SUM(Debit),0) FROM @Items)-(SELECT COALESCE(SUM(Credit),0) FROM @Items))>.01) THROW 51423,'Sales journal details are not balanced.',1;BEGIN TRAN;BEGIN TRY DELETE FROM dbo.SalesDeposit WHERE SalesJournalIdNo=@JournalIdNo;DELETE FROM dbo.SalesJournalItem WHERE JournalIdNo=@JournalIdNo;UPDATE dbo.SalesJournal SET TransactionDate=@TransactionDate,AccountIdNo=@AccountIdNo,ReferenceNo=@ReferenceNo,Notes=@Notes,Approved=@Approved,Posted=@Posted,Cancelled=@Cancelled WHERE IdNo=@JournalIdNo;INSERT dbo.SalesJournalItem(AccountIdNo,Credit,Debit,JournalIdNo,Notes,PayIdNo,RevCostCenterIdNo,Sequence) SELECT AccountIdNo,Credit,Debit,@JournalIdNo,Notes,PayIdNo,RevCostCenterIdNo,Sequence FROM @Items;INSERT dbo.SalesDeposit(DepositTypeIdNo,DepositAmount,SaleAmount,SalesJournalIdNo,Sequence,VatAmount) SELECT DepositTypeIdNo,DepositAmount,SaleAmount,@JournalIdNo,Sequence,VatAmount FROM @Deposits;COMMIT;END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK;THROW;END CATCH END;
GO
